function drawTechnologyCatalog(){
 const root=$('#technologyCatalogList');
 if(!root)return;
 const q=String($('#technologyCatalogSearch')?.value||'').trim().toLowerCase();
 const all=allTech().filter(t=>`${t.name} ${t.category||''} ${t.subcategory||''} ${join(t.tags)}`.toLowerCase().includes(q));
 root.innerHTML=all.slice(0,800).map(t=>{
   const personal=customTechnologies.some(x=>String(x.name).toLowerCase()===String(t.name).toLowerCase());
   const docs=officialDocs.filter(d=>String(d.technologyId||'').toLowerCase()===docTechnologyId(t)||String(d.technology||'').toLowerCase()===String(t.name).toLowerCase());
   return `<article class="card result-card"><div class="result-title">🧩 ${esc(t.name)}</div><p class="muted small">${esc(t.description||'No description saved.')}</p><div class="result-meta"><span class="badge">${esc(t.category||'DevOps')}</span>${t.subcategory?`<span class="badge">${esc(t.subcategory)}</span>`:''}<span class="badge">${esc(t.difficulty||'beginner')}</span><span class="badge">${personal?'Personal override':'Remote catalog'}</span><span class="badge">📖 ${docs.length} docs</span></div>${arr(t.tags).length?`<div class="chips">${arr(t.tags).slice(0,10).map(x=>`<span class="chip">#${esc(x)}</span>`).join('')}</div>`:''}<div class="toolbar"><button data-action="edit-technology" data-id="${esc(t.id||t.name)}">✎ ${personal?'Edit':'Improve / Override'}</button>${docs.length?`<button data-action="technology-section" data-section="docs">📖 Documentation</button>`:''}<button data-action="technology" data-name="${esc(t.name)}">Open</button></div></article>`;
 }).join('')||'<div class="empty-state" style="grid-column:1/-1"><h3>No technologies found</h3><p>Try another search or add a personal technology.</p></div>';
}

async function saveTechnology(){
 const name=$('#tf-name')?.value.trim();
 if(!name){toast('Technology name is required.');return false;}
 const existingId=$('#tf-name')?.dataset.id||'';
 const base=existingId?allTech().find(x=>String(x.id)===String(existingId)||String(x.name).toLowerCase()===String(existingId).toLowerCase()):null;
 const record={
   ...(base?clone(base):{}),
   id:base?.id||existingId||name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),
   name,
   category:$('#tf-category')?.value.trim()||'DevOps',
   subcategory:$('#tf-subcategory')?.value.trim()||'',
   difficulty:$('#tf-difficulty')?.value||'beginner',
   description:$('#tf-description')?.value.trim()||'',
   tags:csv($('#tf-tags')?.value),
   prerequisites:csv($('#tf-prereq')?.value),
   official:{...(base?.official||{}),website:$('#tf-website')?.value.trim()||'',documentation:$('#tf-docs')?.value.trim()||'',github:$('#tf-github')?.value.trim()||''},
   type:'technology',
   updatedAt:new Date().toISOString()
 };
 const key=String(name).toLowerCase();
 const i=customTechnologies.findIndex(x=>String(x.name).toLowerCase()===key||String(x.id)===String(existingId));
 if(i>=0)customTechnologies[i]=record;else customTechnologies.push(record);
 await saveCustomTechnologies(customTechnologies);
 $('#technologyEditor')?.remove();
 await loadData();
 render();
 if(state.page==='technologies'&&state.techSection==='catalog')drawTechnologyCatalog();
 toast(`${name} saved to your personal technology catalog.`);
 return true;
}

async function deleteTechnology(id){
 const t=customTechnologies.find(x=>String(x.id)===String(id)||String(x.name).toLowerCase()===String(id).toLowerCase());
 if(!t)return toast('Only personal technology overrides can be deleted.');
 if(!confirm(`Delete personal technology override "${t.name}"?`))return;
 customTechnologies=customTechnologies.filter(x=>x!==t);
 await saveCustomTechnologies(customTechnologies);
 $('#technologyEditor')?.remove();
 await loadData();
 render();
 if(state.page==='technologies'&&state.techSection==='catalog')drawTechnologyCatalog();
 toast('Personal technology override removed.');
}

